/* ---------- Jadwal salat (hitungan astronomi, 100% offline; Fajr 20°, Isya 18° ala Kemenag) ---------- */
function waktu(d,{lat,lng,tz:TZ}){
  const r=Math.PI/180,tz=TZ??-d.getTimezoneOffset()/60,n=v=>((v+12)%24+24)%24-12;
  const j=Date.UTC(d.getFullYear(),d.getMonth(),d.getDate(),12)/864e5+2440587.5-2451545;
  const g=(357.529+.98560028*j)*r,q=280.459+.98564736*j,L=(q+1.915*Math.sin(g)+.02*Math.sin(2*g))*r,e=23.439*r;
  const ra=Math.atan2(Math.cos(e)*Math.sin(L),Math.cos(L))/r/15,dec=Math.asin(Math.sin(e)*Math.sin(L));
  const noon=12+tz-lng/15-n(q/15-ra),sL=Math.sin(lat*r),cL=Math.cos(lat*r),sD=Math.sin(dec),cD=Math.cos(dec);
  const h=a=>Math.acos(Math.max(-1,Math.min(1,(Math.sin(a*r)-sL*sD)/(cL*cD))))/r/15;
  const asr=Math.atan(1/(1+Math.tan(Math.abs(lat*r-dec))))/r;
  return [['Subuh',noon-h(-20)],['Terbit',noon-h(-.833)],['Zuhur',noon+.0333],['Asar',noon+h(asr)],['Magrib',noon+h(-.833)+.0333],['Isya',noon+h(-18)]];
}
const hm=h=>{const m=Math.round(((h%24)+24)%24*60)%1440;return String(m/60|0).padStart(2,'0')+':'+String(m%60).padStart(2,'0')};
const hijri=(d=new Date())=>new Intl.DateTimeFormat('id-u-ca-islamic-umalqura',{day:'numeric',month:'long',year:'numeric'}).format(d);

/* ---------- Al-Qur'an (teks diunduh sekali, lalu disimpan Service Worker untuk offline) ---------- */
const qUrl=n=>`https://api.alquran.cloud/v1/surah/${n}/editions/quran-uthmani,id.indonesian,en.transliteration`;
const qGet=async n=>{const r=await fetch(qUrl(n));if(!r.ok)throw 0;const d=(await r.json()).data;return d[0].ayahs.map((a,i)=>({a:a.text,t:d[1].ayahs[i].text,l:d[2]?.ayahs?.[i]?.text||''}))};

/* ---------- Zakat (nisab emas 85 g; hasil bumi 653 kg gabah ~ 5 wasaq; dapat diubah di kode) ---------- */
const NIS=85,RATE=.025;
const gold=()=>+S.gold||0;
const zNet=(label,f1,f2)=>({t:label,f:[['a',f1],['b',f2]],run:v=>{const base=v.a-v.b,nis=NIS*gold();return {base,nis,z:base>=nis&&nis>0?base*RATE:0,info:'Harta bersih = '+rp(base)+'. Nisab = 85 g emas = '+rp(nis)+'. Tarif 2,5% jika sudah genap satu tahun (haul).'}}});
const ZK={
 emas:{t:'Simpanan emas & perak',f:[['a','Emas (gram)'],['b','Perak (gram)'],['c','Harga perak /gram (Rp)']],run:v=>{const e=v.a*gold(),p=v.b*(v.c||0),zE=v.a>=NIS?e*RATE:0,zP=v.b>=595?p*RATE:0;return {base:e+p,nis:NIS*gold(),z:zE+zP,info:'Nisab emas 85 g, perak 595 g; masing-masing dihitung sendiri, tarif 2,5%, haul 1 tahun.'}}},
 dagang:zNet('Perdagangan','Modal + keuntungan + piutang lancar (Rp)','Utang jatuh tempo (Rp)'),
 usaha:zNet('Perusahaan','Aset lancar (Rp)','Kewajiban jangka pendek (Rp)'),
 properti:zNet('Properti (hasil sewa)','Hasil sewa setahun (Rp)','Biaya operasional (Rp)'),
 profesi:{t:'Profesi',f:[['a','Penghasilan per bulan (Rp)'],['b','Penghasilan lain per bulan (Rp)'],['c','Cicilan kebutuhan pokok per bulan (Rp)']],run:v=>{const m=v.a+v.b-v.c,nis=NIS*gold();return {base:m*12,nis,z:m*12>=nis&&nis>0?m*RATE:0,info:'Penghasilan bersih setahun dibandingkan nisab 85 g emas. Bila wajib, zakat per bulan = 2,5% dari penghasilan bersih bulanan.'}}},
 tambak:zNet('Tambak / perikanan','Hasil panen setahun (Rp)','Biaya produksi (Rp)'),
 kebun:{t:'Tanaman produktif',f:[['a','Hasil panen (kg)'],['b','Harga /kg (Rp)'],['r','Biaya perawatan',[['.1','Tanpa biaya (10%)'],['.05','Berbiaya (5%)']]]],run:v=>{const w=v.a>=653,kg=w?v.a*v.r:0;return {base:v.a,nis:653,z:kg*v.b,unit:'kg',kg,info:'Dianalogikan dengan hasil pertanian (nisab 653 kg). Ada perbedaan pendapat ulama; konsultasikan dengan lembaga zakat.'}}},
 ternak:{t:'Peternakan',f:[['r','Jenis ternak',[['1','Kambing / domba'],['2','Sapi / kerbau']]],['a','Jumlah ekor']],run:v=>{const n=v.a;let o='Belum mencapai nisab.',z=0;if(v.r==1){if(n>=40)z=n<=120?'1 ekor kambing (domba 1 th / kambing 2 th)':n<=200?'2 ekor kambing':n<=399?'3 ekor kambing':Math.floor(n/100)+' ekor kambing';if(n>=40)o=''}else{if(n>=30)o=n<40?'1 ekor sapi tabi\' (1 th)':n<60?'1 ekor sapi musinnah (2 th)':n<70?'2 ekor sapi tabi\'':'Hitung: tiap 30 ekor = 1 tabi\', tiap 40 ekor = 1 musinnah'}return {txt:z||o,info:'Nisab kambing 40 ekor, sapi 30 ekor; syarat: mencapai haul dan digembalakan (saimah).'}}},
 tani:{t:'Pertanian tanaman pangan',f:[['a','Hasil panen (kg gabah)'],['b','Harga gabah /kg (Rp)'],['r','Pengairan',[['.1','Tadah hujan (10%)'],['.05','Irigasi berbiaya (5%)'],['.075','Campuran (7,5%)']]]],run:v=>{const w=v.a>=653;const kg=w?v.a*v.r:0;return {base:v.a,nis:653,z:kg*v.b,unit:'kg',kg,info:'Nisab 653 kg gabah (5 wasaq), tanpa haul, dikeluarkan saat panen. Zakat: '+kg.toFixed(2)+' kg.'}}}};

/* ---------- Komponen ---------- */
const list=(a,fn)=>`<div class="list">${a.map(fn).join('')}</div>`;
const head=(t,back='#/',x='')=>`<div class="bar"><a class="bk" href="${back=='back'?'javascript:history.back()':back}" aria-label="Kembali">${ic('back',22)}</a><h1>${t}</h1>${x}</div>`;
const tabs=(a,i=0)=>`<div class="tabs">${a.map((x,k)=>`<button data-tab="${k}" class="${k==i?'on':''}">${x}</button>`).join('')}</div>`;
const soon=a=>list(a,(x,i)=>`<a class="row" href="#/segera/${encodeURIComponent(x)}"><span class="num">${i+1}</span><span class="t">${x}<br><small>Segera hadir</small></span>${ic('next',18)}</a>`);
function twoTabs(t,l,r,A,B,back='#/'){return {html:head(t,back)+tabs([l,r])+`<div id="tb">${A}</div>`,init(){$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(x=>x.classList.toggle('on',x==b));$('#tb').innerHTML=b.dataset.tab==0?A:B})}}}

/* ---------- Halaman ---------- */
const P={};
const gps=cb=>navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>{S.loc={lat:p.coords.latitude,lng:p.coords.longitude,n:'Lokasi saya',tz:-new Date().getTimezoneOffset()/60};save();toast('Lokasi diperbarui');cb()},()=>toast('Izin lokasi ditolak. Aktifkan GPS dan izinkan akses.'),{timeout:10000}):toast('Perangkat tidak mendukung lokasi');
P.kiblat=()=>{const r=Math.PI/180,{lat,lng}=S.loc,dl=(39.8262-lng)*r,b=((Math.atan2(Math.sin(dl),Math.cos(lat*r)*Math.tan(21.4225*r)-Math.sin(lat*r)*Math.cos(dl))/r)+360)%360;
 return {html:head('Arah kiblat')+locCard()+`<div class="card" style="text-align:center"><b style="font-size:30px">${b.toFixed(1)}°</b><br><small class="mut">dari utara sejati · ${S.loc.n}</small><div class="needle" id="nd"><i></i></div><p class="mut" id="kh">Atur lokasi lebih dulu, lalu aktifkan kompas dan goyangkan ponsel membentuk angka 8 agar akurat.</p><button class="btn" id="cmp">Aktifkan kompas</button></div>`,
 init(){$('#nd').style.transform=`rotate(${b}deg)`;$('#cmp').onclick=async()=>{try{if(DeviceOrientationEvent.requestPermission&&await DeviceOrientationEvent.requestPermission()!='granted')throw 0}catch(e){return toast('Izin sensor ditolak')}
  const f=e=>{const h=e.webkitCompassHeading??(e.alpha!=null?360-e.alpha:null);if(h==null||!$('#nd'))return;$('#nd').style.transform=`rotate(${b-h}deg)`;$('#kh').textContent='Putar badan hingga panah hijau menghadap ke atas.'};
  addEventListener('deviceorientationabsolute',f,true);addEventListener('deviceorientation',f,true);toast('Kompas aktif')}}}};
P.quran=()=>({html:`<div class="bar"><a class="bk" href="#/">${ic('back',22)}</a><h1>Al-Quran</h1><button class="btn s" onclick="$('#q').focus()">${ic('search',16)} Cari</button></div><input class="in" id="q" type="search" placeholder="Cari surah…">${tabs(['Surah','Juz','Riwayat'])}<div id="ql"></div><div class="card" style="margin-top:16px"><b>Unduh untuk offline</b><p class="mut" style="margin:4px 0 10px">Teks 114 surah dan terjemah diunduh sekali saat online, lalu bisa dibaca tanpa internet.</p><button class="btn" id="dl">Unduh semua surah</button> <small class="mut" id="dp"></small></div>`,
 init(){let tab=0;const draw=()=>{const q=$('#q').value.toLowerCase();let a=NAMA.map((n,i)=>i+1);if(tab==2)a=S.hist;else if(q)a=a.filter(i=>(NAMA[i-1]+i).toLowerCase().includes(q));
  $('#ql').innerHTML=tab==1?list(JUZ,(j,i)=>`<a class="row" href="#/quran/${j[0]}/${j[1]}"><span class="num">${i+1}</span><span class="t">Juz ${i+1}<br><small>${NAMA[j[0]-1]} : ${j[1]}</small></span></a>`):a.length?list(a,i=>`<a class="row" href="#/quran/${i}"><span class="num">${i}</span><span class="t">${NAMA[i-1]}<br><small>${ARTI[i-1]} (${AYAT[i-1]} Ayat)</small></span></a>`):'<div class="card mut">Belum ada riwayat.</div>'};
  $$('[data-tab]').forEach(b=>b.onclick=()=>{tab=+b.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('on',x==b));draw()});$('#q').oninput=draw;draw();
  $('#dl').onclick=async()=>{$('#dl').disabled=true;let ok=0;for(let i=1;i<=114;i++){try{await qGet(i);ok++}catch(e){}$('#dp').textContent=ok+'/114'}toast(ok==114?'Selesai. Al-Qur\'an siap dibaca offline':'Sebagian gagal, cek internet lalu coba lagi');$('#dl').disabled=false}}});
