/* ---------- Tahlil & Yasin (teks Al-Qur'an tampil langsung di halaman) ---------- */
const AY=async(n,a,b)=>{const A=await qGet(n);return A.slice(a?a-1:0,b||A.length).map((x,i)=>`<div class="ay2"><span class="n">${(a||1)+i}</span><div class="ar" style="font-size:${S.fs}px">${x.a}</div>${S.lt&&x.l?`<p class="lt">${x.l}</p>`:''}${S.tr?`<p class="mut" style="margin:4px 0 0">${x.t}</p>`:''}</div>`).join('')};
const TREF={'Hadiah Al-Fatihah':[[1,0,0,'']],'Al-Ikhlas, Al-Falaq, An-Nas':[[112,0,0,'Al-Ikhlas (dibaca 3×)'],[113,0,0,'Al-Falaq'],[114,0,0,'An-Nas']],'Ayat Kursi':[[2,255,255,'']],'Akhir Surah Al-Baqarah':[[2,285,286,'']]};
const tahlilHtml=()=>TH.filter(x=>x[0]!='Surah Yasin'&&(x[1]||TREF[x[0]])).map(x=>`<h3 class="sec">${x[0]}</h3>${x[1]?`<div class="ar2">${x[1]}</div>`:''}${TREF[x[0]]?TREF[x[0]].map(r=>(r[3]?`<h4 class="sub">${r[3]}</h4>`:'')+`<div data-ref="${r[0]}:${r[1]}:${r[2]}"></div>`).join(''):`<p class="mut">${x[2]}</p>`}`).join('');
P.tahlil=()=>({html:head('Tahlil & Yasin','#/',RS)+tabs(['Tahlil','Yasin'])+zoomBar()+'<div id="tb"></div>',init(){let tok=0;const show=async k=>{const t=$('#tb'),my=++tok;t.innerHTML=k?'<p class="mut">Memuat Surah Yasin…</p>':tahlilHtml();try{if(k){const h='<h3 class="sec">Surah Yasin</h3>'+await AY(36);if(my==tok)t.innerHTML=h}else for(const e of $$('[data-ref]',t)){const [n,a,b]=e.dataset.ref.split(':').map(Number);const h=await AY(n,a,b);if(my!=tok)return;e.innerHTML=h}}catch(x){if(my==tok)t.insertAdjacentHTML('beforeend','<div class="card mut" style="margin-top:12px">Teks Al-Qur\'an belum tersimpan di perangkat. Sambungkan internet sekali, atau unduh dari menu Al-Qur\'an.</div>')}};$$('[data-tab]').forEach(b=>b.onclick=()=>{$$('[data-tab]').forEach(x=>x.classList.toggle('on',x==b));show(+b.dataset.tab)});show(0)}});
