const shrink=f=>new Promise(r=>{const i=new Image,u=URL.createObjectURL(f);i.onload=()=>{const s=Math.min(1,1280/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=i.width*s;c.height=i.height*s;c.getContext('2d').drawImage(i,0,0,c.width,c.height);URL.revokeObjectURL(u);c.toBlob(r,'image/jpeg',.72)};i.onerror=()=>r(null);i.src=u});
const b2d=b=>new Promise(o=>{const f=new FileReader;f.onload=()=>o(f.result);f.readAsDataURL(b)});
const rtxt=r=>`*Laporan Fadzkuruuni v${VER}*\nJenis: ${r.jenis}\nNama: ${r.nama||'-'}\nHalaman: ${r.hal||'-'}\n\n${r.pesan}`;
const post=async r=>{const fd=new FormData();['nama','jenis','pesan','hal'].forEach(k=>fd.append(k,r[k]||''));fd.append('versi',VER);if(r.foto)fd.append('foto',r.foto,'foto.jpg');try{const x=await fetch(REPORT.url,{method:'POST',body:fd,mode:REPORT.nocors?'no-cors':'cors',headers:REPORT.nocors?undefined:{Accept:'application/json'}});return x.ok||x.type=='opaque'}catch(e){return false}};
async function flushQ(){if(!REPORT.url||!(S.rq||[]).length||!navigator.onLine)return;const rest=[];for(const q of S.rq){const f=q.foto?await(await fetch(q.foto)).blob():null;if(!await post({...q,foto:f}))rest.push(q)}S.rq=rest;save()}
addEventListener('online',flushQ);flushQ();
async function sendReport(r){const txt=rtxt(r);
 if(REPORT.url){if(await post(r))return 'sent';S.rq=[...(S.rq||[]),{...r,foto:r.foto?await b2d(r.foto):null}];save();return 'queued'}
 if(r.foto&&navigator.canShare){const files=[new File([r.foto],'laporan.jpg',{type:'image/jpeg'})];if(navigator.canShare({files})){try{await navigator.share({files,text:txt,title:'Laporan Fadzkuruuni'});return 'share'}catch(e){return e.name=='AbortError'?'cancel':'wa'}}}
 const w=open(`https://wa.me/${REPORT.wa}?text=${encodeURIComponent(txt)}`,'_blank');if(!w)location.href=`https://wa.me/${REPORT.wa}?text=${encodeURIComponent(txt)}`;return r.foto?'wafoto':'wa'}
P.lapor=()=>({html:head('Laporkan masalah','#/tentang')+`<p class="mut" style="margin:0 0 10px">Menemukan bug atau kesalahan penulisan (Arab, arti, ejaan)? Laporan akan dikirim ke WhatsApp pengembang.</p><label>Nama (opsional)</label><input class="in" id="rn" maxlength="60" placeholder="Nama kamu"><label>Jenis laporan</label>${seg('rj',[['Bug','Bug'],['Salah tulis','Salah tulis'],['Saran','Saran']],'Bug')}<label style="margin-top:12px">Pesan</label><textarea class="in" id="rm" rows="5" maxlength="1500" placeholder="Di halaman mana, apa yang salah, dan seharusnya bagaimana"></textarea><label>Foto atau tangkapan layar (opsional)</label><label class="ph" for="rf">${ic('camera',20)} <span id="rfn">Pilih foto</span></label><input type="file" id="rf" accept="image/*" hidden><img id="rp" alt="Pratinjau foto" hidden><button class="btn" id="rk" style="width:100%;margin-top:12px">Kirim laporan</button>`,
 init(){let J='Bug',F=null;segBind('rj',v=>J=v);
  $('#rf').onchange=async e=>{const f=e.target.files[0];if(!f)return;F=await shrink(f);if(!F){toast('Foto tidak bisa dibaca');return}$('#rfn').textContent=f.name;const p=$('#rp');p.src=URL.createObjectURL(F);p.hidden=false};
  $('#rk').onclick=async()=>{const pesan=$('#rm').value.trim();if(pesan.length<5)return toast('Tulis pesan laporan terlebih dahulu');const b=$('#rk');b.disabled=true;b.textContent='Mengirim…';
   const st=await sendReport({nama:$('#rn').value.trim(),jenis:J,pesan,hal:LAST,foto:F});b.disabled=false;b.textContent='Kirim laporan';if(st=='cancel')return;
   const m={sent:'Laporanmu sudah terkirim. Masukanmu membantu kami memperbaiki Fadzkuruuni.',queued:'Laporanmu tersimpan dan akan dikirim otomatis saat internet tersedia.',share:'Terima kasih. Pastikan laporan terkirim ke WhatsApp pengembang di aplikasi yang terbuka.',wa:'WhatsApp terbuka dengan isi laporanmu. Tekan tombol kirim di sana untuk menyelesaikannya.',wafoto:'WhatsApp terbuka dengan isi laporanmu. Lampirkan fotonya secara manual di chat, lalu tekan kirim.'}[st];
   dlg('Terima kasih atas laporanmu',m,()=>location.hash='#/tentang')}}});


/* ---------- Maulid ---------- */
const ADL=['Pembuka (Inna fatahna…)','Bagian I: Alhamdulillahil ladzi…','Bagian II: Nabba\'anallahu…','Bagian III: Hadza wa qad nasyara…','Bagian IV: Lamma dana waqtu…','Bagian V: Wulidal Habib…','Bagian VI: Hadza wa qad nasya\'a','Bagian VII: Wa atahu jibrilu…','Mahallul Qiyam','Doa (Ad-du\'a)'];
P.maulid=i=>{if(i==5)return {html:head("Maulid Adl-Dliya'ul Lami'",'#/maulid')+'<p class="mut">Daftar bagian. Isi bacaan belum dimuat karena teks bersih dan izin penggunaannya masih disiapkan.</p>'+soon(ADL)};return {html:head('Maulid')+list(MENU.maulid,(m,k)=>`<a class="row" href="${k==5?'#/maulid/5':'#/segera/'+encodeURIComponent(m)}"><span class="num">${k+1}</span><span class="t">${m}<br><small>${k==5?ADL.length+' bagian':'Segera hadir'}</small></span>${ic('next',18)}</a>`)}};
/* ---------- Hadits, kata mutiara, sapaan, kata-kata bergulir ---------- */
P.hadits=()=>({html:head('Hadits Nabi')+'<p class="mut">Hadits masyhur secara ringkas. Periksa kembali ke kitab asli untuk rujukan.</p>'+HADITS.map(h=>`<div class="card" style="margin-bottom:10px"><div class="ar2">${h[0]}</div><p style="margin:6px 0">${h[1]}</p><small class="mut">${h[2]}</small><div style="margin-top:8px"><button class="btn s" data-copy="${esc(h[0]+'\n'+h[1]+'\n('+h[2]+')')}">Salin</button></div></div>`).join('')});
P.mutiara=()=>({html:head('Kata Mutiara')+QUOTES.map(q=>q[1]).concat(S.qs||[]).map(t=>`<div class="card" style="margin-bottom:10px"><p style="margin:0 0 8px">“${esc(t)}”</p><button class="btn s" data-copy="${esc(t)}">Salin</button></div>`).join('')});
const periode=()=>{const h=locNow();return h<4?'malam':h<10?'pagi':h<15?'siang':h<18?'sore':'malam'};
const GREET=()=>`<div class="gr"><small class="mut">${new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})} · ${hijri()}</small><div class="gh">Selamat ${periode()}${S.nm?', '+esc(S.nm):''}</div></div>`;
function qrot(){const el=$('#qtx');if(!el)return;let i=Math.floor(Math.random()*97);const show=()=>{const e=$('#qtx');if(!e)return clearInterval(P.tq);const p=periode(),L=[...QUOTES.filter(q=>q[0]==p||q[0]=='any').map(q=>q[1]),...(S.qs||[])];e.classList.remove('in');void e.offsetWidth;e.textContent=L[i++%L.length]||'';e.classList.add('in')};show();clearInterval(P.tq);P.tq=setInterval(show,9000)}
/* ---------- Izin, offline, profil ---------- */
const bdg=n=>`<span class="bdg" data-perm="${n}">…</span>`;
const IZIN=()=>`<h2>Izin</h2><div class="list sg">${row('pin','Lokasi salat',bdg('geolocation'),'<button class="btn s" data-loc>Atur lokasi</button>')}${row('bell','Notifikasi',bdg('notifications'),'<button class="btn s" data-notif>Izinkan</button>')}</div>`;
async function permFill(){for(const el of $$('[data-perm]')){const n=el.dataset.perm;let s='Belum diminta';try{const r=await navigator.permissions.query({name:n});s={granted:'Diizinkan',denied:'Ditolak',prompt:'Belum diminta'}[r.state]||s}catch(e){if(n=='notifications'&&'Notification'in window)s={granted:'Diizinkan',denied:'Ditolak',default:'Belum diminta'}[Notification.permission]||s}el.textContent=s;el.className='bdg '+(s=='Diizinkan'?'':s=='Ditolak'?'no':'mid')}}
const OFFL=()=>`<h2>Mode offline</h2><div class="card"><p class="mut" style="margin:0 0 6px">Aplikasi bisa dibuka tanpa internet setelah dimuat sekali. Unduh teks Al-Qur'an agar tetap bisa dibaca tanpa sinyal.</p>${row('book',"Al-Qur'an (114 surah)",'<span id="oq">Menghitung…</span>','<button class="btn s" id="od">Unduh</button>')}${row('clock','Jadwal salat','Dihitung langsung di perangkat, selalu tersedia offline','')}</div>`;
async function offFill(){try{const k=await (await caches.open('fz-data')).keys(),n=k.filter(r=>/surah\//.test(r.url)).length;$('#oq').textContent=n+' dari 114 surah tersimpan'}catch(e){$('#oq').textContent='Belum ada data tersimpan'}$('#od').onclick=async()=>{const b=$('#od');b.disabled=true;let ok=0;for(let i=1;i<=114;i++){try{await qGet(i);ok++}catch(e){}$('#oq').textContent='Mengunduh '+ok+'/114…'}b.disabled=false;toast(ok==114?"Al-Qur'an siap dibaca offline":'Sebagian gagal; cek internet lalu coba lagi');offFill()}}
const PROFIL=()=>`<h2>Profil</h2><div class="list sg"><div class="srw"><span class="si">${ic('user',20)}</span><span class="t">Nama panggilan<br><small class="mut">Dipakai pada sapaan di Beranda</small></span><input class="in sl2" id="nm" maxlength="24" style="width:150px" value="${esc(S.nm||'')}" placeholder="Nama"></div></div><h2>Kata-kata di Beranda</h2><div class="card"><p class="mut" style="margin:0 0 8px">Kata-kata bergulir di bawah jam dan berganti sesuai waktu (pagi, siang, sore, malam). Tambahkan kata-katamu sendiri.</p><div style="display:flex;gap:8px"><input class="in" id="qn" maxlength="140" placeholder="Tulis kata-kata…" style="margin:0"><button class="btn" data-addq>Tambah</button></div>${(S.qs||[]).map((q,i)=>`<div class="sw"><span>${esc(q)}</span><button class="btn s" data-delq="${i}">Hapus</button></div>`).join('')}</div>`;
/* ---------- Akun Google & sinkron cloud (butuh konfigurasi Firebase; lihat PANDUAN-FIREBASE.md) ---------- */
const FBCFG={apiKey:'',authDomain:'',projectId:'',appId:''};
const cloudOn=()=>!!(FBCFG.apiKey&&FBCFG.projectId);
let FBU=null,FBD=null,cpt=0;const SYNC=['bm','hist','nm','qs','theme','fs','tr','lt','tas','tt','rnd','az','loc','pay','ft','full'];
const ldjs=src=>new Promise((o,r)=>{const e=document.createElement('script');e.src=src;e.onload=o;e.onerror=r;document.head.append(e)});
async function fbInit(){if(!cloudOn()||window.firebase?.apps?.length)return;try{const b='https://www.gstatic.com/firebasejs/10.12.2/';await ldjs(b+'firebase-app-compat.js');await ldjs(b+'firebase-auth-compat.js');await ldjs(b+'firebase-firestore-compat.js');firebase.initializeApp(FBCFG);FBD=firebase.firestore();firebase.auth().onAuthStateChanged(async u=>{FBU=u;if(u)await cloudPull();if($('#cl'))route()})}catch(e){}}
async function cloudPull(){try{const d=await FBD.collection('users').doc(FBU.uid).get();if(d.exists){const r=d.data();if((r.t||0)>(S.ct||0)){SYNC.forEach(k=>{if(r.s&&r.s[k]!==undefined&&r.s[k]!==null)S[k]=r.s[k]});S.ct=r.t;localStorage.fz=JSON.stringify(S);theme()}}else cloudSend()}catch(e){toast('Sinkron gagal. Periksa koneksi.')}}
const cloudSend=async()=>{if(!FBU)return;const s={};SYNC.forEach(k=>s[k]=S[k]??null);const t=Date.now();S.ct=t;localStorage.fz=JSON.stringify(S);try{await FBD.collection('users').doc(FBU.uid).set({s,t})}catch(e){}};
window.cloudPush=()=>{if(!FBU)return;clearTimeout(cpt);cpt=setTimeout(cloudSend,2500)};
const AKUN=()=>`<h2>Akun</h2><div class="list sg" id="cl">${cloudOn()?(FBU?row('user',esc(FBU.displayName||'Akun Google'),esc(FBU.email||'')+' · data tersinkron ke cloud','<button class="btn s" data-gout>Keluar</button>'):row('user','Masuk dengan Google','Simpan penanda, riwayat, dan pengaturan di cloud','<button class="btn" data-gin>Masuk</button>')):row('user','Masuk dengan Google','Belum diaktifkan. Isi konfigurasi Firebase (lihat PANDUAN-FIREBASE.md).','<button class="btn s" disabled>Segera</button>')}</div>`;
cloudOn()&&fbInit();
/* ---------- Pendengar tambahan ---------- */
document.addEventListener('input',e=>{if(e.target.id=='nm'){S.nm=e.target.value;save()}});
document.addEventListener('click',async e=>{const t=e.target;
 if(t.closest('[data-rs]'))return qsheet(()=>route());
 if(t.closest('[data-stop]'))return stopAdzan();
 if(t.closest('[data-tsub]'))return play(0);
 if(t.closest('[data-notif]')){await askNotif();return permFill()}
 if(t.closest('[data-gin]'))return firebase.auth().signInWithPopup(new firebase.auth.GoogleAuthProvider()).catch(()=>toast('Masuk dibatalkan atau gagal'));
 if(t.closest('[data-gout]'))return firebase.auth().signOut().then(()=>{FBU=null;route()});
 if(t.closest('[data-addq]')){const v=($('#qn').value||'').trim();if(!v)return toast('Tulis kata-katanya dulu');S.qs=[...(S.qs||[]),v];save();return route()}
 const d=t.closest('[data-delq]');if(d){S.qs.splice(+d.dataset.delq,1);save();route()}});

/* ---------- Router ---------- */
function route(){if(!location.hash.startsWith('#/lapor'))LAST=location.hash||'#/';$('#au')?.pause();const [a='',b,c,d]=location.hash.slice(2).split('/');const pg=a=='quran'&&b?surah(b,c):(P[a]||P[''])(b,c,d);document.body.classList.toggle('full',!!S.full&&a=='quran'&&!!b);const v=$('#view');v.innerHTML=pg.html;v.scrollTop=0;v.style.animation='none';v.offsetWidth;v.style.animation='';
 $$('#nav a[data-r]').forEach(l=>l.classList.toggle('on',l.dataset.r==(['quran','artikel','kalender','pengaturan'].includes(a)?a:(['','menu'].includes(a)?'':'x'))));pg.init&&pg.init();$$('#view .ar2').forEach(e=>e.style.fontSize=S.fs+'px');ftUpd();
 $$('[data-soon]').forEach(e=>e.onclick=()=>toast('Konten ini segera hadir'))}
addEventListener('hashchange',route);route();
if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('sw.js').catch(()=>{}));
